// 这里仍防一手整数回绕）。
func sumMaterialGrams(b *batchRecord, materialNo string) (sum gramsMilli, ok bool) {
	for _, f := range b.Feedings {
		if f.MaterialNo != materialNo {
			continue
		}
		if f.GramsMilli > maxGramsMilli-sum {
			return maxGramsMilli, false
		}
		sum += f.GramsMilli
	}
	return sum, true
}

