package release

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// 绑定 v1（只有 M1、M2）的批次保存了 M3 投料：即使 v2 已登记且含 M3，
// Open 也必须返回 ErrCorruptData，错误信息指出批次、物料、配方编号与版本。
func TestTmpOpenRejectsFeedingMaterialNotInBoundVersion(t *testing.T) {
	dir := t.TempDir()
	r1v1 := &recipeRecord{RecipeNo: "R1", Version: "v1", Name: "配方一",
		Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 100000}, {MaterialNo: "M2", GramsMilli: 500}}}
	r1v2 := &recipeRecord{RecipeNo: "R1", Version: "v2", Name: "配方一",
		Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 100000}, {MaterialNo: "M3", GramsMilli: 2000}}}
	r2v1 := &recipeRecord{RecipeNo: "R2", Version: "v1", Name: "配方二",
		Materials: []materialRecord{{MaterialNo: "M3", GramsMilli: 2000}}}
	original := writeStateFile(t, dir, &persistedState{
		Version: stateVersion,
		Recipes: []*recipeRecord{r1v1, r1v2, r2v1},
		Batches: []*batchRecord{
			{BatchNo: "B-ok", RecipeNo: "R1", RecipeVersion: "v2", PlannedPortions: 1, Status: StatusExecuting},
			{BatchNo: "B-bad", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 2, Status: StatusExecuting,
				Feedings: []feedingRecord{
					{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
					{Seq: 2, MaterialNo: "M3", GramsMilli: 500, Time: time.Now(), Registrar: "张三"},
				}},
		},
	})

	s, err := Open(dir)
	if !errors.Is(err, ErrCorruptData) {
		t.Fatalf("非绑定版本物料的已保存投料应返回 ErrCorruptData，得到 %v", err)
	}
	if s != nil {
		s.Close()
		t.Fatalf("损坏台账不应返回可用的 Store 对象")
	}
	msg := err.Error()
	for _, want := range []string{"B-bad", "M3", "R1", "v1"} {
		if !strings.Contains(msg, want) {
			t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
		}
	}
	if !strings.Contains(msg, "不属于") {
		t.Fatalf("错误信息应说明物料不属于绑定版本，得到 %v", err)
	}
	got, err := os.ReadFile(filepath.Join(dir, stateFileName))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(got, original) {
		t.Fatalf("拒绝打开不应改动台账文件")
	}
}

// 打开后文件被改坏（投料物料不属于绑定版本）：查询与写入都失败，
// 被拒绝的写入不占用请求编号；正常台账行为不受影响。
func TestTmpMaterialCorruptionAfterOpen(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
		{MaterialNo: "M1", Grams: "100"}, {MaterialNo: "M2", Grams: "0.5"},
	}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
		t.Fatal(err)
	}
	if _, err := s.StartBatch("s1", "B1"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddFeeding("f1", "B1", "M1", "5", time.Now(), "张三"); err != nil {
		t.Fatal(err)
	}

	// 正常追加非配方物料仍返回 ErrMaterialNotInRecipe，而非 ErrCorruptData。
	if _, err := s.AddFeeding("f-bad", "B1", "M9", "1", time.Now(), "张三"); !errors.Is(err, ErrMaterialNotInRecipe) {
		t.Fatalf("新提交的非配方物料应返回 ErrMaterialNotInRecipe，得到 %v", err)
	}

	// 改坏文件：把已保存投料的物料改成配方外的 M9。
	good, err := os.ReadFile(filepath.Join(dir, stateFileName))
	if err != nil {
		t.Fatal(err)
	}
	var broken persistedState
	if err := jsonUnmarshal(good, &broken); err != nil {
		t.Fatal(err)
	}
	broken.Batches[0].Feedings[0].MaterialNo = "M9"
	badBytes := writeStateFile(t, dir, &broken)

	if _, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
		t.Fatalf("查询应返回 ErrCorruptData，得到 %v", err)
	}
	if _, err := s.AddFeeding("f2", "B1", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
		t.Fatalf("写入应返回 ErrCorruptData，得到 %v", err)
	}
	after, err := os.ReadFile(filepath.Join(dir, stateFileName))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(after, badBytes) || bytes.Contains(after, []byte("f2")) {
		t.Fatalf("被拒绝的写入不应改动文件或占用请求编号")
	}

	// 恢复后正常，f2 可重新提交。
	if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddFeeding("f2", "B1", "M1", "1", time.Now(), "李四"); err != nil {
		t.Fatalf("恢复后 f2 应可提交: %v", err)
	}
}

